class Solution {
public:
    int countTime(std::string time) {
        int ans = 0;
        for (int h = 0; h < 24; h++) {
            for (int m = 0; m < 60; m++) {
                char buf[6];
                std::snprintf(buf, sizeof(buf), "%02d:%02d", h, m);
                bool match = true;
                for (int i = 0; i < 5; i++) {
                    if (time[i] != '?' && time[i] != buf[i]) {
                        match = false;
                        break;
                    }
                }
                if (match) ans++;
            }
        }
        return ans;
    }
};

class Solution {
    public int countTime(String time) {
        int ans = 0;
        for (int h = 0; h < 24; h++) {
            for (int m = 0; m < 60; m++) {
                String formatted = String.format("%02d:%02d", h, m);
                boolean match = true;
                for (int i = 0; i < 5; i++) {
                    if (time.charAt(i) != '?' && time.charAt(i) != formatted.charAt(i)) {
                        match = false;
                        break;
                    }
                }
                if (match) ans++;
            }
        }
        return ans;
    }
}

var countTime = function(time) {
    let ans = 0;
    for (let h = 0; h < 24; h++) {
        for (let m = 0; m < 60; m++) {
            const formatted = String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
            let match = true;
            for (let i = 0; i < 5; i++) {
                if (time[i] !== '?' && time[i] !== formatted[i]) {
                    match = false;
                    break;
                }
            }
            if (match) ans++;
        }
    }
    return ans;
};
